#ifndef VEXEL_BASE_BASE_H
#define VEXEL_BASE_BASE_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

typedef enum base_status {
    BASE_STATUS_OK = 0,
    BASE_STATUS_INVALID,
    BASE_STATUS_OVERFLOW,
    BASE_STATUS_LIMIT,
    BASE_STATUS_OOM
} base_status;

typedef struct base_bytes {
    const uint8_t *ptr;
    size_t len;
} base_bytes;

typedef struct base_mut_bytes {
    uint8_t *ptr;
    size_t len;
} base_mut_bytes;

typedef void *(*base_alloc_fn)(size_t size, void *context);
typedef void (*base_free_fn)(void *ptr, void *context);

typedef struct base_allocator {
    base_alloc_fn alloc;
    base_free_fn free;
    void *context;
} base_allocator;

typedef struct base_arena base_arena;

typedef struct base_arena_config {
    size_t initial_chunk_bytes;
    size_t capacity_limit;
    base_allocator allocator;
} base_arena_config;

typedef struct base_arena_stats {
    size_t chunk_count;
    size_t payload_capacity;
    size_t used_bytes;
} base_arena_stats;

bool base_size_add(size_t a, size_t b, size_t *out);
bool base_size_mul(size_t a, size_t b, size_t *out);

bool base_bytes_valid(base_bytes bytes);
bool base_mut_bytes_valid(base_mut_bytes bytes);
bool base_bytes_sub(base_bytes bytes, size_t offset, size_t length, base_bytes *out);
bool base_mut_bytes_sub(base_mut_bytes bytes, size_t offset, size_t length, base_mut_bytes *out);
bool base_bytes_equal(base_bytes left, base_bytes right);

base_status base_arena_create(const base_arena_config *config, base_arena **out);
base_status base_arena_push(base_arena *arena, size_t size, size_t alignment, void **out);
bool base_arena_get_stats(const base_arena *arena, base_arena_stats *out);
void base_arena_reset(base_arena *arena);
void base_arena_destroy(base_arena *arena);

#endif
#ifndef VEXEL_XML_TOKENIZER_H
#define VEXEL_XML_TOKENIZER_H

#include "base.h"

#include <stddef.h>
#include <stdint.h>

typedef enum svg_xml_token_kind {
    SVG_XML_TOKEN_DECLARATION = 1,
    SVG_XML_TOKEN_PROCESSING_INSTRUCTION,
    SVG_XML_TOKEN_COMMENT,
    SVG_XML_TOKEN_START_ELEMENT,
    SVG_XML_TOKEN_END_ELEMENT,
    SVG_XML_TOKEN_EMPTY_ELEMENT,
    SVG_XML_TOKEN_ATTRIBUTE,
    SVG_XML_TOKEN_TEXT,
    SVG_XML_TOKEN_CDATA,
    /* A skipped <!DOCTYPE>; source spans the whole declaration, never expanded. */
    SVG_XML_TOKEN_DOCTYPE
} svg_xml_token_kind;

typedef enum svg_xml_error {
    SVG_XML_ERROR_NONE = 0,
    SVG_XML_ERROR_INVALID_ARGUMENT,
    SVG_XML_ERROR_INPUT_LIMIT,
    SVG_XML_ERROR_INVALID_UTF8,
    SVG_XML_ERROR_INVALID_CHARACTER,
    SVG_XML_ERROR_UNSUPPORTED_ENCODING,
    SVG_XML_ERROR_INVALID_NAME,
    SVG_XML_ERROR_MALFORMED_SYNTAX,
    SVG_XML_ERROR_DUPLICATE_ATTRIBUTE,
    SVG_XML_ERROR_MISMATCHED_TAG,
    SVG_XML_ERROR_DEPTH_LIMIT,
    SVG_XML_ERROR_NODE_LIMIT,
    SVG_XML_ERROR_ATTRIBUTE_LIMIT,
    SVG_XML_ERROR_TEXT_LIMIT,
    SVG_XML_ERROR_OUTPUT_EXHAUSTED,
    SVG_XML_ERROR_UNSUPPORTED_DTD,
    SVG_XML_ERROR_MULTIPLE_ROOTS,
    SVG_XML_ERROR_INCOMPLETE_DOCUMENT
} svg_xml_error;

typedef struct svg_xml_span {
    size_t offset;
    size_t length;
} svg_xml_span;

typedef struct svg_xml_token {
    svg_xml_token_kind kind;
    svg_xml_span source;
    svg_xml_span name;
    svg_xml_span value;
    svg_xml_span prefix;
    svg_xml_span local_name;
    size_t depth;
} svg_xml_token;

typedef struct svg_xml_limits {
    size_t input_bytes;
    size_t nesting_depth;
    size_t nodes;
    size_t attributes_per_element;
    size_t total_attributes;
    size_t text_run_bytes;
} svg_xml_limits;

typedef struct svg_xml_options {
    svg_xml_limits limits;
} svg_xml_options;

typedef struct svg_xml_diagnostic {
    svg_xml_error category;
    size_t offset;
} svg_xml_diagnostic;

typedef struct svg_xml_result {
    size_t token_count;
    size_t element_count;
    size_t attribute_count;
    size_t node_count;
    svg_xml_diagnostic diagnostic;
} svg_xml_result;

typedef bool (*svg_xml_cancel_check_fn)(void *context);
/* Returning false cancels visitor delivery. Token spans borrow immutable input. */
typedef bool (*svg_xml_token_visitor_fn)(void *context, const svg_xml_token *token);

typedef struct svg_xml_token_stream svg_xml_token_stream;
typedef enum svg_xml_stream_status {
    SVG_XML_STREAM_OK = 0,
    SVG_XML_STREAM_COMPLETE,
    SVG_XML_STREAM_FAILED,
    SVG_XML_STREAM_CANCELED
} svg_xml_stream_status;

svg_xml_options svg_xml_default_options(void);
svg_xml_result svg_xml_tokenize(base_bytes input, svg_xml_options options,
                                svg_xml_token *tokens, size_t token_capacity);
/* Same grammar and non-input limits as the default API; allows up to 1 GiB input. */
svg_xml_result svg_xml_tokenize_large(base_bytes input, svg_xml_token *tokens,
                                      size_t token_capacity);
svg_xml_result svg_xml_tokenize_large_cancelable(base_bytes input, svg_xml_token *tokens,
    size_t token_capacity, svg_xml_cancel_check_fn canceled, void *cancel_context);
/* Borrows immutable input until destroy; max_storage_bytes bounds its token vector. */
svg_xml_stream_status svg_xml_token_stream_start(base_bytes input, size_t max_storage_bytes,
    svg_xml_cancel_check_fn canceled, void *cancel_context, svg_xml_token_stream **out_stream);
/* Discard-mode stream; retains only fixed scanner state and the active tag's bounded tokens. */
svg_xml_stream_status svg_xml_token_stream_start_visitor(base_bytes input,
    svg_xml_token_visitor_fn visitor, void *visitor_context,
    svg_xml_cancel_check_fn canceled, void *cancel_context,
    svg_xml_token_stream **out_stream);
/* Resumes validation/token emission under one shared byte budget, capped at 64 KiB. */
svg_xml_stream_status svg_xml_token_stream_step(svg_xml_token_stream *stream, size_t byte_budget);
